'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8');
let pos = 0;

function nextInt() {
  while (pos < input.length && input.charCodeAt(pos) <= 32) pos++;
  let value = 0;
  while (pos < input.length) {
    const c = input.charCodeAt(pos);
    if (c < 48 || c > 57) break;
    value = value * 10 + c - 48;
    pos++;
  }
  return value;
}

function gcd(a, b) {
  while (b !== 0) {
    const t = a % b;
    a = b;
    b = t;
  }
  return a;
}

function leaf(value) {
  const groupsG = [value];
  const groupsW = [1];
  return {
    total: value,
    answer: value > 1 ? 1 : 0,
    pg: groupsG,
    pw: groupsW,
    sg: groupsG,
    sw: groupsW
  };
}

function merge(left, right) {
  if (!left) return right;
  if (!right) return left;

  let cross = 0;
  let j = right.pg.length - 1;
  let remaining = right.pw.reduce((sum, count) => sum + count, 0);

  for (let i = 0; i < left.sg.length; i++) {
    const value = left.sg[i];
    while (j >= 0 && gcd(value, right.pg[j]) === 1) {
      remaining -= right.pw[j];
      j--;
    }
    cross += left.sw[i] * remaining;
  }

  const total = gcd(left.total, right.total);

  const pg = left.pg.slice();
  const pw = left.pw.slice();
  for (let i = 0; i < right.pg.length; i++) {
    const value = gcd(left.total, right.pg[i]);
    const last = pg.length - 1;
    if (pg[last] === value) pw[last] += right.pw[i];
    else {
      pg.push(value);
      pw.push(right.pw[i]);
    }
  }

  const sg = right.sg.slice();
  const sw = right.sw.slice();
  for (let i = 0; i < left.sg.length; i++) {
    const value = gcd(left.sg[i], right.total);
    const last = sg.length - 1;
    if (sg[last] === value) sw[last] += left.sw[i];
    else {
      sg.push(value);
      sw.push(left.sw[i]);
    }
  }

  return {
    total,
    answer: left.answer + right.answer + cross,
    pg,
    pw,
    sg,
    sw
  };
}

const N = nextInt();
const M = nextInt();

let size = 1;
while (size < N) size <<= 1;

const tree = new Array(size << 1).fill(null);
for (let i = 0; i < N; i++) {
  tree[size + i] = leaf(nextInt());
}

for (let i = size - 1; i > 0; i--) {
  tree[i] = merge(tree[i << 1], tree[(i << 1) | 1]);
}

const output = [];

for (let q = 0; q < M; q++) {
  const type = nextInt();
  const x = nextInt();
  const y = nextInt();

  if (type === 1) {
    let index = size + x - 1;
    tree[index] = leaf(y);
    index >>= 1;

    while (index > 0) {
      tree[index] = merge(tree[index << 1], tree[(index << 1) | 1]);
      index >>= 1;
    }
  } else {
    let left = size + x - 1;
    let right = size + y;
    let leftResult = null;
    let rightResult = null;

    while (left < right) {
      if (left & 1) {
        leftResult = merge(leftResult, tree[left]);
        left++;
      }
      if (right & 1) {
        right--;
        rightResult = merge(tree[right], rightResult);
      }
      left >>= 1;
      right >>= 1;
    }

    const result = merge(leftResult, rightResult);
    output.push(String(result.answer));
  }
}

process.stdout.write(output.join('\n'));
